{
  "section_id": "graph",
  "section": {
    "node_model": {
      "canonical_entity": "node",
      "canonical_body_fields": [
        "title",
        "content",
        "summary"
      ],
      "removed_body_fields": [
        "kind",
        "node_type",
        "hypothesis",
        "insights",
        "no_artifacts_reason"
      ],
      "node_reference_fields": [
        "node_id",
        "slug_name"
      ],
      "slug_name": {
        "format": "adjective-noun-####",
        "generated_on_create": true,
        "mutable": false,
        "nullable_for_legacy_nodes": true
      }
    },
    "operation_catalog_ref": {
      "tool": "flywheel_get_contract",
      "path": "contract.operations"
    },
    "modeling_guidance": {
      "node_semantics": {
        "insight": "observations, theoretical insights, intuitions, motivations, decision framing",
        "empirical": "experiments with explicit hypotheses, methods, and measured outcomes"
      },
      "topology": "prefer logical/causal graph relations over shallow root-only branching, unless workstreams are independent",
      "graph_scaling": "when the visible graph becomes large, suggest clustering connected related nodes with shared cluster tags so zoomed-out views stay efficient and legible"
    },
    "durable_contract_rules": [
      "Node state is canonical durable state; avoid relying on ephemeral transcript state.",
      "Node body state is title, Markdown content, and optional summary; do not write typed body fields such as kind, node_type, hypothesis, insights, or no_artifacts_reason.",
      "Node references include immutable `node_id` and optional immutable `slug_name`; prefer communicating both together for human clarity and disambiguation.",
      "Use Markdown structure, tags, artifacts, and executions to represent observations, decisions, experiments, and evidence.",
      "Graph topology should encode logical/causal relations between concepts and experiments. Avoid defaulting to shallow root-only branching unless work items are truly independent."
    ]
  }
}

